H('418.d.8.E',3,"A force that pulls a member apart is called:","tension",["compression","bearing","shear"],"Tension stretches.")
H('418.d.8.E',4,"A force that tends to slide one part of a member past an adjacent part is:","shear",["tension","compression","buoyancy"],"Shear slides layers.")
